<?php require 'includes/bootstrap.php';require_login();$q=db()->prepare('SELECT * FROM sites WHERE user_id=? ORDER BY created_at DESC');$q->execute([user_id()]);$sites=$q->fetchAll();header_html('لوحة التحكم'); ?>
<section class="wrapper section"><div class="dashboard-heading"><div><span class="eyebrow">لوحة التحكم</span><h1 class="page-title">مواقعي الإلكترونية</h1><p class="lead">كل مواقع مشروعك في مكان واحد.</p></div><a class="button primary" href="create.php">+ إنشاء موقع جديد</a></div><?php if (isset($_GET['saved'])):?><div class="alert success">تم حفظ التغييرات بنجاح.</div><?php endif;?><?php if (isset($_GET['deleted'])):?><div class="alert success">تم حذف الموقع.</div><?php endif;?><?php if(!$sites):?><div class="empty-state"><span>✳</span><h2>لم تبدأ بعد؟</h2><p>أنشئ موقعك الأول في دقائق.</p><a class="button primary" href="create.php">أنشئ موقعي</a></div><?php else:?><div class="site-grid"><?php foreach($sites as $site):?><article class="site-card"><div class="site-icon theme-<?=e($site['template'])?>">✳</div><div><h2><?=e($site['business_name'])?></h2><p><?=e($site['tagline'])?></p><small><?=e($site['slug'])?></small></div><div class="site-actions"><a href="site.php?slug=<?=urlencode($site['slug'])?>" target="_blank" rel="noopener">عرض الموقع ↗</a><a href="edit.php?id=<?=(int)$site['id']?>">تعديل</a><form method="post" action="delete.php" data-confirm="هل تريد حذف هذا الموقع نهائيًا؟"><?=csrf_input()?><input type="hidden" name="id" value="<?=(int)$site['id']?>"><button type="submit" class="danger-link">حذف</button></form></div></article><?php endforeach;?></div><?php endif;?></section><?php footer_html(); ?>
